  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Heino Falcke",
        "Sheperd S. Doeleman",
        "James M. Moran"
      ],
      "assessment": {
        "nobel_worthiness": "The Event Horizon Telescope turned a central prediction of strong-field gravity into a directly resolved image, with exceptional public and scientific impact.",
        "attribution": "The result depended on a global interferometric array and a large collaboration. These names represent theoretical advocacy, array leadership, and foundational very-long-baseline interferometry contributions, though the full attribution needs careful review.",
        "maturity": "The 2019 M87* image and subsequent black-hole imaging provide independent, durable confirmation of the capability and result.",
        "uncertainties": [
          "The Nobel's limit of three laureates makes credit across the EHT collaboration especially difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page Jr.",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's full-sky precision mapping of the cosmic microwave background established a quantitative standard model of cosmology and transformed the study of the early universe.",
        "attribution": "Bennett and Page led major experimental and instrumental work; Spergel helped establish the cosmological interpretation. Credit should reflect the broad team behind the mission.",
        "maturity": "Its central cosmological results have been repeatedly checked and extended by later observations, including Planck.",
        "uncertainties": [
          "The work overlaps in subject and scientific legacy with the 2006 prize for CMB discovery and anisotropy."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Peter W. Shor",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite noise, making scalable quantum computation conceptually possible and reshaping quantum information physics.",
        "attribution": "Shor and Steane introduced landmark codes, while Kitaev developed influential topological approaches. The intellectual development was broad, and the distinct contributions need careful separation.",
        "maturity": "The principles are established and underpin active experimental demonstrations, although large-scale fault-tolerant quantum computing remains unrealized.",
        "uncertainties": [
          "It is not yet clear whether the field's ultimate scientific impact will be primarily fundamental or technological."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle"
      ],
      "assessment": {
        "nobel_worthiness": "The detection of high-energy astrophysical neutrinos opened a new observational channel on the most energetic cosmic accelerators and launched neutrino astronomy.",
        "attribution": "Halzen's leadership and sustained advocacy, together with Karle's central contributions to IceCube, represent key scientific and experimental roles; the collaboration's work is essential to the achievement.",
        "maturity": "The diffuse astrophysical neutrino flux is established, with growing evidence linking it to source populations.",
        "uncertainties": [
          "The sources and acceleration mechanisms behind much of the observed flux remain incompletely identified."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "John A. Peacock",
        "Shaun Cole"
      ],
      "assessment": {
        "nobel_worthiness": "The detection and development of baryon acoustic oscillations as a standard ruler created a powerful, independent method for measuring cosmic expansion and dark energy.",
        "attribution": "These candidates span the landmark observational detection and its theoretical and survey foundations; the relative credit for the discovery and subsequent precision method deserves scrutiny.",
        "maturity": "BAO measurements have been replicated across many surveys and are now a central part of precision cosmology.",
        "uncertainties": [
          "The discovery involved substantial contributions from multiple teams, and the boundary between initial detection and later exploitation is not sharp."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics established a practical and conceptually clear way to couple superconducting qubits to microwave photons, enabling control of light-matter interactions at the quantum level.",
        "attribution": "Blais developed the key theoretical framework, while Wallraff and Schoelkopf helped demonstrate and advance the experimental architecture. This balances theory with realization.",
        "maturity": "The platform has been reproduced widely and supports increasingly sophisticated quantum experiments and processors.",
        "uncertainties": [
          "Its eventual standing may be as an enabling platform within the larger story of quantum information rather than a distinct discovery."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Alexander Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is a remarkable conceptual connection between quantum field theory and gravity that has influenced high-energy theory, condensed matter, and black-hole research.",
        "attribution": "Maldacena's concrete duality proposal is the central discovery; Witten and Polyakov made major foundational contributions to the surrounding theoretical framework and its development.",
        "maturity": "The duality has been tested in many mathematical and theoretical settings, but its physical relevance to our universe has not been experimentally established.",
        "uncertainties": [
          "The absence of direct empirical confirmation is a serious obstacle for recognizing this as a physics discovery."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Nial R. Tanvir"
      ],
      "assessment": {
        "nobel_worthiness": "The observed kilonova following a neutron-star merger connected gravitational-wave astronomy with heavy-element production and provided compelling evidence for r-process nucleosynthesis in these events.",
        "attribution": "Metzger and Kasen helped establish the kilonova interpretation and predictions; Tanvir contributed important observational work. The result rests on coordinated theory and multi-messenger observations.",
        "maturity": "The GW170817 counterpart was a major confirmation, but the relative contribution of neutron-star mergers to the cosmic inventory of heavy elements remains under study.",
        "uncertainties": [
          "The evidence does not yet settle how much of the r-process material is produced by this channel compared with other possible sources."
        ]
      }
    }
  ]
}
